import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import styles from './LoginPage.module.css';

const LoginPage = () => {
    const navigate = useNavigate();
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);
        try {
            await login(email, password);
            navigate('/');
        } catch (err) {
            setError(err.message || 'Ошибка входа');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className={styles.loginPage}>
            <div className={styles.container}>
                <div className={styles.loginCard}>
                    <div className={styles.header}>
                        <div className={styles.logo}>🏐</div>
                        <h1 className={styles.title}>Вход в аккаунт</h1>
                        <p className={styles.subtitle}>Добро пожаловать обратно!</p>
                    </div>
                    <form onSubmit={handleSubmit} className={styles.form}>
                        {error && <div className={styles.errorMessage}>{error}</div>}
                        <Input label="Email" type="email" placeholder="Введите ваш email" value={email} onChange={(e) => setEmail(e.target.value)} required />
                        <PasswordInput label="Пароль" placeholder="Введите пароль" value={password} onChange={(e) => setPassword(e.target.value)} />
                        <Button type="submit" fullWidth size="large" loading={loading}>Войти</Button>
                    </form>
                    <div className={styles.footer}>
                        <p className={styles.registerLink}>Нет аккаунта? <a href="/register">Зарегистрироваться</a></p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;
